create or replace function private.validate_print_layout(tenant uuid,layout jsonb) returns public.exam_versions language plpgsql security definer set search_path='' as $$
begin
 if layout ? 'printStyle' and (jsonb_typeof(layout->'printStyle') is distinct from 'string' or layout->>'printStyle' not in ('classic','compact','school','school-v2')) then raise exception 'INVALID_PRINT_LAYOUT'; end if;
 return private.validate_print_layout_v2(tenant,layout-'printStyle');
end; $$;
alter function private.validate_print_text_fit(jsonb) rename to validate_print_text_fit_v4;
create function private.validate_print_text_fit(layout jsonb) returns void language plpgsql immutable set search_path='' as $$
declare width double precision:=case when layout->>'paperMode'='full' then 297 else 148.5 end;
begin
 if coalesce(layout->>'printStyle','classic')<>'school-v2' then perform private.validate_print_text_fit_v4(layout); return; end if;
 if private.print_v5_width(layout->>'school',3.1,true)>width-79.5
   or private.print_v5_width(layout->>'title',4.2,true)>2*(width-80)
   or private.print_v5_width('วิชา …'||(layout->>'subject')||'… · …'||(layout->>'examType')||'…',2.8,true)>2*(width-57)
   or private.print_v5_width(layout->>'instructions',2.6)>3*(width-24.5) then raise exception 'PRINT_TEXT_DOES_NOT_FIT'; end if;
end; $$;
alter function private.expected_print_geometry(jsonb) rename to expected_print_geometry_v4;
create function private.expected_print_geometry(layout jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare geometry jsonb;
begin
 if coalesce(layout->>'printStyle','classic')<>'school-v2' then return private.expected_print_geometry_v4(layout); end if;
 geometry:=private.expected_print_geometry_v4(jsonb_set(layout,'{printStyle}','"school"'));
 return jsonb_set(geometry,'{geometryVersion}','5');
end; $$;
